  1178  /* Parse seconds in the form ss or ss.sss (variable length decimal) */
  1179  static gboolean
  1180  get_iso8601_seconds (const gchar *text, gsize length, gdouble *value)
  1181  {
  1182    gsize i;
  1183    gdouble divisor = 1, v = 0;
  1184
  1185    if (length < 2)
  1186      return FALSE;
  1187
  1188    for (i = 0; i < 2; i++)
  1189      {
  1190        const gchar c = text[i];
  1191        if (c < '0' || c > '9')
  1192          return FALSE;
  1193        v = v * 10 + (c - '0');
  1194      }
  1195
  1196    if (length > 2 && !(text[i] == '.' || text[i] == ','))
  1197      return FALSE;
  1198
  1199    /* Ignore leap seconds, see g_date_time_new_from_iso8601() */
  1200    if (v >= 60.0 && v <= 61.0)
  1201      v = 59.0;
  1202
  1203    i++;
  1204    if (i == length)
  1205      return FALSE;
  1206
  1207    for (; i < length; i++)
  1208      {
  1209        const gchar c = text[i];
  1210        if (c < '0' || c > '9')
  1211          return FALSE;
  1212        v = v * 10 + (c - '0');
  1213        divisor *= 10;
  1214      }
  1215
  1216    *value = v / divisor;
  1217    return TRUE;
  1218  }
