  1220  static GDateTime *
  1221  g_date_time_new_ordinal (GTimeZone *tz, gint year, gint ordinal_day, gint hour, gint minute, gdouble seconds)
  1222  {
  1223    GDateTime *dt;
  1224
  1225    if (ordinal_day < 1 || ordinal_day > (GREGORIAN_LEAP (year) ? 366 : 365))
  1226      return NULL;
  1227
  1228    dt = g_date_time_new (tz, year, 1, 1, hour, minute, seconds);
  1229    if (dt == NULL)
  1230      return NULL;
  1231    dt->days += ordinal_day - 1;
  1232
  1233    return dt;
  1234  }
