  1236  static GDateTime *
  1237  g_date_time_new_week (GTimeZone *tz, gint year, gint week, gint week_day, gint hour, gint minute, gdouble seconds)
  1238  {
  1239    gint64 p;
  1240    gint max_week, jan4_week_day, ordinal_day;
  1241    GDateTime *dt;
  1242
  1243    p = (year * 365 + (year / 4) - (year / 100) + (year / 400)) % 7;
  1244    max_week = p == 4 ? 53 : 52;
  1245
  1246    if (week < 1 || week > max_week || week_day < 1 || week_day > 7)
  1247      return NULL;
  1248
  1249    dt = g_date_time_new (tz, year, 1, 4, 0, 0, 0);
  1250    if (dt == NULL)
  1251      return NULL;
  1252    g_date_time_get_week_number (dt, NULL, &jan4_week_day, NULL);
  1253    g_date_time_unref (dt);
  1254
  1255    ordinal_day = (week * 7) + week_day - (jan4_week_day + 3);
  1256    if (ordinal_day < 0)
  1257      {
  1258        year--;
  1259        ordinal_day += GREGORIAN_LEAP (year) ? 366 : 365;
  1260      }
  1261    else if (ordinal_day > (GREGORIAN_LEAP (year) ? 366 : 365))
  1262      {
  1263        ordinal_day -= (GREGORIAN_LEAP (year) ? 366 : 365);
  1264        year++;
  1265      }
  1266
  1267    return g_date_time_new_ordinal (tz, year, ordinal_day, hour, minute, seconds);
  1268  }
