  1270  static GDateTime *
  1271  parse_iso8601_date (const gchar *text, gsize length,
  1272                      gint hour, gint minute, gdouble seconds, GTimeZone *tz)
  1273  {
  1274    /* YYYY-MM-DD */
  1275    if (length == 10 && text[4] == '-' && text[7] == '-')
  1276      {
  1277        int year, month, day;
  1278        if (!get_iso8601_int (text, 4, &year) ||
  1279            !get_iso8601_int (text + 5, 2, &month) ||
  1280            !get_iso8601_int (text + 8, 2, &day))
  1281          return NULL;
  1282        return g_date_time_new (tz, year, month, day, hour, minute, seconds);
  1283      }
  1284    /* YYYY-DDD */
  1285    else if (length == 8 && text[4] == '-')
  1286      {
  1287        gint year, ordinal_day;
  1288        if (!get_iso8601_int (text, 4, &year) ||
  1289            !get_iso8601_int (text + 5, 3, &ordinal_day))
  1290          return NULL;
  1291        return g_date_time_new_ordinal (tz, year, ordinal_day, hour, minute, seconds);
  1292      }
  1293    /* YYYY-Www-D */
  1294    else if (length == 10 && text[4] == '-' && text[5] == 'W' && text[8] == '-')
  1295      {
  1296        gint year, week, week_day;
  1297        if (!get_iso8601_int (text, 4, &year) ||
  1298            !get_iso8601_int (text + 6, 2, &week) ||
  1299            !get_iso8601_int (text + 9, 1, &week_day))
  1300          return NULL;
  1301        return g_date_time_new_week (tz, year, week, week_day, hour, minute, seconds);
  1302      }
  1303    /* YYYYWwwD */
  1304    else if (length == 8 && text[4] == 'W')
  1305      {
  1306        gint year, week, week_day;
  1307        if (!get_iso8601_int (text, 4, &year) ||
  1308            !get_iso8601_int (text + 5, 2, &week) ||
  1309            !get_iso8601_int (text + 7, 1, &week_day))
  1310          return NULL;
  1311        return g_date_time_new_week (tz, year, week, week_day, hour, minute, seconds);
  1312      }
  1313    /* YYYYMMDD */
  1314    else if (length == 8)
  1315      {
  1316        int year, month, day;
  1317        if (!get_iso8601_int (text, 4, &year) ||
  1318            !get_iso8601_int (text + 4, 2, &month) ||
  1319            !get_iso8601_int (text + 6, 2, &day))
  1320          return NULL;
  1321        return g_date_time_new (tz, year, month, day, hour, minute, seconds);
  1322      }
  1323    /* YYYYDDD */
  1324    else if (length == 7)
  1325      {
  1326        gint year, ordinal_day;
  1327        if (!get_iso8601_int (text, 4, &year) ||
  1328            !get_iso8601_int (text + 4, 3, &ordinal_day))
  1329          return NULL;
  1330        return g_date_time_new_ordinal (tz, year, ordinal_day, hour, minute, seconds);
  1331      }
  1332    else
  1333      return FALSE;
  1334  }
