  1336  static GTimeZone *
  1337  parse_iso8601_timezone (const gchar *text, gsize length, gssize *tz_offset)
  1338  {
  1339    gint i, tz_length, offset_hours, offset_minutes;
  1340    gint offset_sign = 1;
  1341    GTimeZone *tz;
  1342
  1343    /* UTC uses Z suffix  */
  1344    if (length > 0 && text[length - 1] == 'Z')
  1345      {
  1346        *tz_offset = length - 1;
  1347        return g_time_zone_new_utc ();
  1348      }
  1349
  1350    /* Look for '+' or '-' of offset */
  1351    for (i = length - 1; i >= 0; i--)
  1352      if (text[i] == '+' || text[i] == '-')
  1353        {
  1354          offset_sign = text[i] == '-' ? -1 : 1;
  1355          break;
  1356        }
  1357    if (i < 0)
  1358      return NULL;
  1359    tz_length = length - i;
  1360
  1361    /* +hh:mm or -hh:mm */
  1362    if (tz_length == 6 && text[i+3] == ':')
  1363      {
  1364        if (!get_iso8601_int (text + i + 1, 2, &offset_hours) ||
  1365            !get_iso8601_int (text + i + 4, 2, &offset_minutes))
  1366          return NULL;
  1367      }
  1368    /* +hhmm or -hhmm */
  1369    else if (tz_length == 5)
  1370      {
  1371        if (!get_iso8601_int (text + i + 1, 2, &offset_hours) ||
  1372            !get_iso8601_int (text + i + 3, 2, &offset_minutes))
  1373          return NULL;
  1374      }
  1375    /* +hh or -hh */
  1376    else if (tz_length == 3)
  1377      {
  1378        if (!get_iso8601_int (text + i + 1, 2, &offset_hours))
  1379          return NULL;
  1380        offset_minutes = 0;
  1381      }
  1382    else
  1383      return NULL;
  1384
  1385    *tz_offset = i;
  1386    tz = g_time_zone_new_identifier (text + i);
  1387
  1388    /* Double-check that the GTimeZone matches our interpretation of the timezone.
  1389     * This can fail because our interpretation is less strict than (for example)
  1390     * parse_time() in gtimezone.c, which restricts the range of the parsed
  1391     * integers. */
  1392    if (tz == NULL || g_time_zone_get_offset (tz, 0) != offset_sign * (offset_hours * 3600 + offset_minutes * 60))
  1393      {
  1394        g_clear_pointer (&tz, g_time_zone_unref);
  1395        return NULL;
  1396      }
  1397
  1398    return tz;
  1399  }
