  1401  static gboolean
  1402  parse_iso8601_time (const gchar *text, gsize length,
  1403                      gint *hour, gint *minute, gdouble *seconds, GTimeZone **tz)
  1404  {
  1405    gssize tz_offset = -1;
  1406
  1407    /* Check for timezone suffix */
  1408    *tz = parse_iso8601_timezone (text, length, &tz_offset);
  1409    if (tz_offset >= 0)
  1410      length = tz_offset;
  1411
  1412    /* hh:mm:ss(.sss) */
  1413    if (length >= 8 && text[2] == ':' && text[5] == ':')
  1414      {
  1415        return get_iso8601_int (text, 2, hour) &&
  1416               get_iso8601_int (text + 3, 2, minute) &&
  1417               get_iso8601_seconds (text + 6, length - 6, seconds);
  1418      }
  1419    /* hhmmss(.sss) */
  1420    else if (length >= 6)
  1421      {
  1422        return get_iso8601_int (text, 2, hour) &&
  1423               get_iso8601_int (text + 2, 2, minute) &&
  1424               get_iso8601_seconds (text + 4, length - 4, seconds);
  1425      }
  1426    else
  1427      return FALSE;
  1428  }
